const GNK_ASG_LOGO_DATA_URI = "data:image/png;base64,";
const GNK_DINAMO_LTD_LOGO_DATA_URI = "data:image/png;base64,";
const GNK_ASG_LOGO_SOURCE_NAME = "05_GNK_ASG_logo_brand_board_HR.png";
const GNK_DINAMO_LTD_LOGO_SOURCE_NAME = "07_GNK_DINAMO_LTD_brand_board_NO_D_SYMBOL.png";
const GNK_ASG_LOGO_SOURCE_PATH = "G:\\GNK\\GNK_ASG_LOGO_SELECTION_20260616_181527\\logo-candidates\\05_GNK_ASG_logo_brand_board_HR.png";
const GNK_DINAMO_LTD_LOGO_SOURCE_PATH = "G:\\GNK\\GNK_ASG_LOGO_SELECTION_20260616_181527\\logo-candidates\\07_GNK_DINAMO_LTD_brand_board_NO_D_SYMBOL.png";

function safeName(value){
  return String(value || "").replace(/[<>&"']/g, "");
}

function logoSvgResponse(kind){
  const isDinamo = kind === "dinamo";
  const dataUri = isDinamo ? GNK_DINAMO_LTD_LOGO_DATA_URI : GNK_ASG_LOGO_DATA_URI;
  const sourceName = safeName(isDinamo ? GNK_DINAMO_LTD_LOGO_SOURCE_NAME : GNK_ASG_LOGO_SOURCE_NAME);
  const title = isDinamo ? "GNK DINAMO Ltd." : "GNK ASG";
  const headerKind = isDinamo ? "gnk-dinamo-ltd-selected-logo-7-v1" : "gnk-asg-selected-logo-5-v1";

  const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">' +
    '<defs><radialGradient id="bg" cx="35%" cy="20%" r="80%"><stop offset="0%" stop-color="#1e3a66"/><stop offset="55%" stop-color="#07101f"/><stop offset="100%" stop-color="#020308"/></radialGradient><linearGradient id="gold" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#fff1a6"/><stop offset="45%" stop-color="#f5d776"/><stop offset="100%" stop-color="#9f7c22"/></linearGradient><clipPath id="r"><rect x="54" y="54" width="404" height="404" rx="86"/></clipPath></defs>' +
    '<rect x="18" y="18" width="476" height="476" rx="112" fill="url(#bg)" stroke="url(#gold)" stroke-width="22"/>' +
    '<g clip-path="url(#r)"><rect x="54" y="54" width="404" height="404" fill="rgba(255,255,255,.94)"/><image href="' + dataUri + '" x="64" y="64" width="384" height="384" preserveAspectRatio="xMidYMid meet"/></g>' +
    '<rect x="18" y="18" width="476" height="476" rx="112" fill="none" stroke="#f5d776" stroke-width="6" opacity=".55"/>' +
    '<title>' + title + ' logo source: ' + sourceName + '</title>' +
    '</svg>';

  return new Response(svg, {
    headers: {
      "content-type": "image/svg+xml; charset=utf-8",
      "cache-control": "public, max-age=3600",
      "x-gnk-asg-brand-asset": headerKind,
      "x-gnk-asg-logo-source": sourceName
    }
  });
}

export function gnkAsgFaviconSvgResponse(){
  return logoSvgResponse("asg");
}

export function gnkAsgLogoSvgResponse(){
  return logoSvgResponse("asg");
}

export function gnkDinamoLtdLogoSvgResponse(){
  return logoSvgResponse("dinamo");
}

export function gnkAsgLogosJsonResponse(){
  const data = {
    ok: true,
    version: "selected-logos-5-7-v1",
    updatedAt: new Date().toISOString(),
    logos: {
      gnkAsg: {
        selectedNumber: 5,
        endpoint: "/brand/gnk-asg-logo.svg",
        favicon: "/favicon.svg",
        sourceName: GNK_ASG_LOGO_SOURCE_NAME,
        sourcePath: GNK_ASG_LOGO_SOURCE_PATH
      },
      gnkDinamoLtd: {
        selectedNumber: 7,
        endpoint: "/brand/gnk-dinamo-ltd-logo.svg",
        sourceName: GNK_DINAMO_LTD_LOGO_SOURCE_NAME,
        sourcePath: GNK_DINAMO_LTD_LOGO_SOURCE_PATH
      }
    }
  };

  return new Response(JSON.stringify(data, null, 2), {
    headers: {
      "content-type": "application/json; charset=utf-8",
      "cache-control": "no-store, max-age=0",
      "x-gnk-asg-brand-asset": "selected-logos-5-7-v1"
    }
  });
}
